const std::vector<PhaseCapability>& PhaseRegistry::all()const{return phases_;}
std::vector<PhaseCapability> PhaseRegistry::domain(int m)const{std::vector<PhaseCapability>r;for(auto&p:phases_)if(p.major==m)r.push_back(p);return r;}
std::optional<PhaseCapability> PhaseRegistry::find(int a,int b)const{for(auto&p:phases_)if(p.major==a&&p.minor==b)return p;return{};}
bool PhaseRegistry::complete()const{if(phases_.empty())return false;for(int m=30;m<=39;m++){auto d=domain(m);if(d.empty()||d.front().minor!=0)return false;}return true;}
LinuxDomain::LinuxDomain(int m):major_(m){}
std::string LinuxDomain::name()const{static const std::map<int,std::string>n={{30,"resources"},{31,"services"},{32,"storage"},{33,"network"},{34,"accelerators"},{35,"software"},{36,"configuration"},{37,"secrets"},{38,"identity"},{39,"timeline"}};auto i=n.find(major_);return i==n.end()?"unknown":i->second;}
std::vector<std::string> LinuxDomain::providers()const{std::vector<std::string>r;switch(major_){case 30:r={"procfs","sysfs"};if(fs::exists("/proc/pressure"))r.push_back("psi");if(fs::exists("/sys/fs/cgroup"))r.push_back("cgroup-v2");break;case 31:if(cmd("systemctl"))r.push_back("systemd");break;case 32:r={"sysfs","proc-mounts","statvfs"};if(cmd("lsblk"))r.push_back("util-linux");break;case 33:r={"sysfs","proc-net"};if(cmd("ip"))r.push_back("iproute2");break;case 34:r={"sysfs-pci","drm"};if(cmd("nvidia-smi"))r.push_back("nvidia-smi");break;case 35:if(cmd("dpkg"))r.push_back("dpkg");if(cmd("apt"))r.push_back("apt");if(cmd("flatpak"))r.push_back("flatpak");if(cmd("snap"))r.push_back("snap");break;case 36:r={"filesystem","environment"};if(cmd("systemd-analyze"))r.push_back("systemd");break;case 37:r={"redacted-environment-metadata"};if(cmd("secret-tool"))r.push_back("libsecret");break;case 38:r={"passwd","group","procfs"};if(cmd("loginctl"))r.push_back("logind");break;case 39:r={"clock_gettime","proc-boot-id"};if(cmd("journalctl"))r.push_back("journald");break;}return r;}
std::vector<Object> LinuxDomain::discover()const{std::vector<Object>r;std::error_code ec;switch(major_){case 30:{auto m=rf("/proc/meminfo");r.push_back({"cpu","cpu","procfs","observed",{{"online",std::to_string(sysconf(_SC_NPROCESSORS_ONLN))}}});r.push_back({"memory","memory","procfs",m.empty()?"unavailable":"observed",{{"source","/proc/meminfo"}}});break;}case 31:{for(auto&e:fs::directory_iterator("/run/systemd/system",ec))if(e.path().extension()==".service")r.push_back({e.path().filename().string(),"service","systemd","known",{}});break;}case 32:{for(auto&e:fs::directory_iterator("/sys/class/block",ec))r.push_back({e.path().filename().string(),"block-device","sysfs","observed",{}});break;}case 33:{for(auto&e:fs::directory_iterator("/sys/class/net",ec)){auto id=e.path().filename().string();r.push_back({id,"interface","sysfs",tr(rf(e.path()/"operstate")),{{"mtu",tr(rf(e.path()/"mtu"))}}});}break;}case 34:{for(auto&e:fs::directory_iterator("/sys/class/drm",ec)){auto id=e.path().filename().string();if(id.rfind("card",0)==0&&id.find('-')==std::string::npos)r.push_back({id,"gpu","drm","observed",{}});}break;}case 35:{std::ifstream f("/var/lib/dpkg/status");std::string l,pkg,st;while(std::getline(f,l)){if(l.rfind("Package: ",0)==0)pkg=l.substr(9);else if(l.rfind("Status: ",0)==0)st=l.substr(8);else if(l.empty()&&!pkg.empty()){if(st.find("installed")!=std::string::npos)r.push_back({pkg,"package","dpkg","installed",{}});pkg.clear();st.clear();}}break;}case 36:{for(auto p:{"/etc/os-release","/etc/fstab","/etc/hostname","/etc/systemd"})if(fs::exists(p))r.push_back({p,"configuration","filesystem","present",{}});break;}case 37:{for(char**e=::environ;*e;e++){std::string s=*e;auto q=s.find('=');auto k=s.substr(0,q);std::string u=k;std::transform(u.begin(),u.end(),u.begin(),::toupper);if(u.find("TOKEN")!=std::string::npos||u.find("SECRET")!=std::string::npos||u.find("PASSWORD")!=std::string::npos||u.find("KEY")!=std::string::npos)r.push_back({k,"secret-reference","environment","redacted",{{"material","<redacted>"}}});}break;}case 38:{std::ifstream f("/etc/passwd");std::string l;while(std::getline(f,l)){std::stringstream s(l);std::string user,x,uid;std::getline(s,user,':');std::getline(s,x,':');std::getline(s,uid,':');r.push_back({uid,"user","passwd","present",{{"username",user}}});}break;}case 39:{auto boot=tr(rf("/proc/sys/kernel/random/boot_id"));r.push_back({boot,"boot","kernel","current",{{"boot_id",boot}}});break;}}return r;}
DomainHealth LinuxDomain::health()const{DomainHealth h;auto p=providers();auto o=discover();h.available=!p.empty();h.provider=p.empty()?"none":p.front();h.metrics={{"providers",std::to_string(p.size())},{"objects",std::to_string(o.size())}};if(!h.available)h.issues.push_back("no provider available");return h;}
Decision LinuxDomain::validate(const Change&c,bool confirmed,bool privileged)const{if(c.domain!=name())return{false,"change belongs to another domain",{}};if(c.action.empty()||c.target.empty())return{false,"action and target are required",{}};if(c.destructive&&!confirmed)return{false,"destructive change requires explicit confirmation",{}};if(c.privileged&&!privileged)return{false,"privileged change requires privilege boundary",{}};if(major_==37&&c.desired.contains("material"))return{false,"secret material must not cross the metadata/control boundary",{}};return{true,"change validated; execution remains delegated to typed provider/executor",{{name(),"validate",c.target,true}}};}
Fields LinuxDomain::snapshot()const{auto h=health();Fields f=h.metrics;f["domain"]=name();f["provider"]=h.provider;f["available"]=h.available?"true":"false";return f;}
System3039::System3039():resources(30),services(31),storage(32),network(33),accelerators(34),software(35),configuration(36),secrets(37),identity(38),timeline(39){}
ClosureReport System3039::audit()const{ClosureReport r;r.registered_phases=phases.all().size();r.ready=phases.complete();for(auto*d:{&resources,&services,&storage,&network,&accelerators,&software,&configuration,&secrets,&identity,&timeline}){auto h=d->health();r.domains[d->major()]=h.available;if(!h.available){r.ready=false;r.issues.push_back(d->name()+": no provider");}}if(r.registered_phases!=624){r.ready=false;r.issues.push_back("phase registry count mismatch");}return r;}
